pub fn check_operation_gate(
    case_space: &CaseSpace,
    gate: &NativeOperationGate,
    expected_operation: &str,
) -> Result<(), NativeOperationGateError> {
    let failures = operation_gate_failures(case_space, gate, expected_operation);
    if failures.is_empty() {
        return Ok(());
    }
    let witness_ids = failures
        .iter()
        .flat_map(|failure| failure.witness_ids.iter().cloned())
        .collect();
    let labels = failures
        .iter()
        .map(|failure| failure.message.as_str())
        .collect::<Vec<_>>()
        .join("; ");
    // All or nothing, and only for a case space the store would accept.
    //
    // `operation_gate_failures` does not short-circuit, so a wrong scope and
    // an unauthorized capability can refuse together — and the recovery for
    // the two is opposite: copy a value and retry, versus stop and escalate
    // to someone holding the capability. Reporting the mismatch alone in that
    // mixed case would tell a caller its authority was never evaluated when
    // it was evaluated and denied, and on `plan accept` that is the
    // always-human checkpoint in `docs/security/worker-execution-policy.md`
    // being read as a retry loop.
    //
    // The second condition is the same argument one step later: an expected
    // value is only worth handing back if the append that follows the retry
    // can succeed, and on a case space that fails the evaluability contract
    // it cannot — the retry passes this gate and dies at the append with
    // `store_integrity`, forever. That applied to the source boundary first,
    // then to an incomplete boundary object; review found it applies to the
    // operation scope too, so it lives here, once, for every field rather
    // than beside any one of them.
    //
    // Asked here rather than in `operation_gate_failures` for a second
    // reason: that function runs on every gate check including the ones that
    // pass, and the validator walks every cell, relation, projection and log
    // entry. Computing it there cost a full scan per check and multiplied
    // per step under `run --frontier` — measured at 2.6s where main took
    // under a millisecond. Here it is reached only when the gate has already
    // failed *and* every clause is a value a caller could otherwise copy,
    // which is rare and already on the error path.
    let mismatches = failures
        .iter()
        .filter_map(|failure| failure.mismatch.clone())
        .collect::<Vec<_>>();
    let all_mechanical = !mismatches.is_empty() && mismatches.len() == failures.len();
    let unevaluable =
        all_mechanical && crate::native_eval::validate_native_case_space(case_space).is_err();
    let field_mismatches = if all_mechanical && !unevaluable {
        mismatches
    } else {
        Vec::new()
    };
    let evaluability_note = if unevaluable {
        "; no expected value is offered because this case space does not satisfy the store's \
         evaluability contract, so retrying with it would pass this gate and then be refused \
         when the mutation is appended — this state should be investigated rather than retried"
    } else {
        ""
    };
    Err(NativeOperationGateError {
        message: format!(
            "operation gate for {expected_operation:?} violates: {labels}{evaluability_note}"
        ),
        witness_ids,
        field_mismatches,
    })
}

fn policy_capability_gate_invariant(
    case_space: &CaseSpace,
    request: &NativeCloseCheckRequest,
) -> NativeCloseInvariantResult {
    let has_close_policy =
        request.close_policy_id.is_some() || case_space.close_policy_id.is_some();
    let has_operation_source = !request.source_ids.is_empty();
    let mut witness_ids = Vec::new();
    if !has_close_policy {
        witness_ids.push(case_space.case_space_id.clone());
    }
    if !has_operation_source {
        witness_ids.push(case_space.revision.revision_id.clone());
    }
    let Some(gate) = &request.operation_gate else {
        witness_ids.push(case_space.case_space_id.clone());
        return close_invariant(
            "close:native-policy-capability-gate",
            dedupe_ids(witness_ids),
            "Close checks must include an operation gate with actor, capability, scope, audience, and source boundary.",
        );
    };
    if let Err(error) = check_operation_gate(case_space, gate, "close-check") {
        witness_ids.extend(error.witness_ids);
    }
    close_invariant(
        "close:native-policy-capability-gate",
        dedupe_ids(witness_ids),
        "Close checks must name a close policy, source evidence, and a matching operation gate for actor, capability, scope, audience, and source boundary.",
    )
}
